# RSASSA-PKCS1-v1_5 signing (`std/crypto/rsasign`) against independent
# references, all generated by `gen/rsasign_vectors.py`:
# - rsavectors/openssl.txt: `openssl dgst -sign` with the throwaway keys of
#   rsakeys/ (2048, 3072, 4096 bits), each key read as PKCS#8 and PKCS#1, PEM
#   and DER; the signatures must be byte-identical.
# - rsavectors/wycheproof_siggen.txt and nist_siggen15.txt: signature
#   generation vectors with their private keys.
# - rsavectors/wycheproof_messages.txt: the messages of Wycheproof's
#   verification-only files, signed here and verified with std/crypto/rsa.
# - rsakeys/bad/dp-corrupt.der: a key that parses but cannot sign.

import std/[syncio, strutils, base64]
import std/crypto/[rsa, rsasign]

const
  OpensslTxt = slurp("rsavectors/openssl.txt")
  WycheproofTxt = slurp("rsavectors/wycheproof_siggen.txt")
  NistTxt = slurp("rsavectors/nist_siggen15.txt")
  MessagesTxt = slurp("rsavectors/wycheproof_messages.txt")
  DpCorrupt = slurp("rsakeys/bad/dp-corrupt.der")
  Keys = [
    ("test2048", slurp("rsakeys/test2048.pkcs8.pem"), slurp("rsakeys/test2048.pkcs1.pem")),
    ("test2048b", slurp("rsakeys/test2048b.pkcs8.pem"), ""),
    ("test3072", slurp("rsakeys/test3072.pkcs8.pem"), slurp("rsakeys/test3072.pkcs1.pem")),
    ("test4096", slurp("rsakeys/test4096.pkcs8.pem"), slurp("rsakeys/test4096.pkcs1.pem"))]
  JwtClaims = """{"iss":"nimony-test@example.iam.gserviceaccount.com",""" &
    """"scope":"https://www.googleapis.com/auth/devstorage.read_only",""" &
    """"aud":"https://oauth2.googleapis.com/token","exp":1767229200,"iat":1767225600}"""

proc bytesOf(s: string): seq[byte] =
  result = @[]
  for c in s: result.add byte(c)

proc hexVal(c: char): int =
  if c in {'0'..'9'}: ord(c) - ord('0')
  elif c in {'a'..'f'}: ord(c) - ord('a') + 10
  else: ord(c) - ord('A') + 10

proc unhex(s: string): seq[byte] =
  result = @[]
  if s == "-": return
  var i = 0
  while i + 1 < s.len:
    result.add byte(hexVal(s[i]) * 16 + hexVal(s[i+1]))
    i += 2

proc hashOf(s: string): RsaHash =
  case s
  of "384": rhSha384
  of "512": rhSha512
  else: rhSha256

proc pemBody(pem: string): seq[byte] =
  ## The DER inside a PEM block, decoded with std/base64 (not the
  ## parser's own decoder).
  var body = ""
  var inside = false
  for line in pem.splitLines:
    if line.startsWith("-----BEGIN"): inside = true
    elif line.startsWith("-----END"): inside = false
    elif inside: body.add line
  result = bytesOf(decode(body))

# --- the example of `rsaSignPkcs1v15`'s doc comment, verbatim ---

proc base64Url(data: openArray[byte]): string =
  ## base64url without padding, as JWS wants it.
  result = encode(data, safe = true)
  while result.len > 0 and result[result.len - 1] == '=':
    result.setLen(result.len - 1)

proc base64Url(s: string): string =
  var b: seq[byte] = @[]
  for c in s: b.add byte(c)
  result = base64Url(b)

proc signJwt(pem, claims: string; jwt: var string): bool =
  ## `header.claims.signature`; `false` if the key is refused.
  jwt = ""
  var key = default(RsaPrivateKey)
  if parseRsaPrivateKeyPem(pem, key) != rkeNone: return false
  let input = base64Url("""{"alg":"RS256","typ":"JWT"}""") & "." &
              base64Url(claims)
  var bytes: seq[byte] = @[]
  for c in input: bytes.add byte(c)
  var sig: seq[byte] = @[]
  if rsaSignPkcs1v15(key, rhSha256, bytes, sig) != rseNone: return false
  jwt = input & "." & base64Url(sig)
  result = true

# ---

proc message(name: string): seq[byte] =
  case name
  of "empty": result = @[]
  of "hello": result = bytesOf("hello nimony")
  of "jwt": result = bytesOf(base64Url("""{"alg":"RS256","typ":"JWT"}""") & "." &
                             base64Url(JwtClaims))
  else:
    result = newSeq[byte](65536)
    for i in 0 ..< result.len: result[i] = byte(i mod 251)

proc signs(key: RsaPrivateKey; h: RsaHash; msg, expected: openArray[byte]): bool =
  ## Signs, compares with `expected` and verifies with std/crypto/rsa.
  var sig: seq[byte] = @[]
  result = rsaSignPkcs1v15(key, h, msg, sig) == rseNone and sig == @expected and
           rsaVerifyPkcs1v15(publicKey(key), h, msg, sig)

proc opensslGoldens =
  echo "-- openssl dgst -sign"
  for (name, pem8, pem1) in Keys:
    var encodings: seq[(string, RsaKeyError, RsaPrivateKey)] = @[]
    var k = default(RsaPrivateKey)
    encodings.add ("PKCS#8 PEM", parseRsaPrivateKeyPem(pem8, k), k)
    encodings.add ("PKCS#8 DER", parseRsaPrivateKeyDer(pemBody(pem8), k), k)
    if pem1.len > 0:
      encodings.add ("PKCS#1 PEM", parseRsaPrivateKeyPem(pem1, k), k)
      encodings.add ("PKCS#1 DER", parseRsaPrivateKeyDer(pemBody(pem1), k), k)
    for (enc, err, key) in encodings:
      var same = 0
      var total = 0
      for line in OpensslTxt.splitLines:
        let f = line.split(' ')
        if f.len == 5 and f[0] == "s" and f[1] == name:
          inc total
          if signs(key, hashOf(f[2]), message(f[3]), unhex(f[4])): inc same
      echo name, " ", enc, ": ", err, ", ", same, " of ", total, " identical"

proc jwtExample =
  echo "-- RS256 JWT (the doc comment's example)"
  for (name, pem8, pem1) in Keys:
    var jwt = ""
    let ok = signJwt(pem8, JwtClaims, jwt)
    var expected = ""
    for line in OpensslTxt.splitLines:
      if line.startsWith("j " & name & " "): expected = line.substr(name.len + 3)
    echo name, ": ", ok, ", equals openssl's: ", jwt == expected and expected.len > 0
  var jwt = "x"
  echo "refused key: ", signJwt("not a key", JwtClaims, jwt), " \"", jwt, "\""

proc vectorFile(title, text: string; format: proc (der: openArray[byte]; key: var RsaPrivateKey): RsaKeyError) =
  ## A key the parser refuses skips its tests; the reasons are listed.
  var key = default(RsaPrivateKey)
  var err = rkeNone
  var keys = 0
  var reasons = ""
  var same = 0
  var total = 0
  var skipped = 0
  var failed = ""
  for line in text.splitLines:
    let f = line.split(' ')
    if f.len == 2 and f[0] == "key":
      inc keys
      err = format(unhex(f[1]), key)
      if err != rkeNone: reasons.add "\n  refused: " & $err
    elif f.len == 5 and f[0] == "t":
      if err != rkeNone: inc skipped
      else:
        inc total
        if signs(key, hashOf(f[1]), unhex(f[3]), unhex(f[4])): inc same
        else: failed.add " " & f[2]
  echo title, ": ", keys, " keys, ", same, " of ", total, " signatures identical, ",
       skipped, " skipped", (if failed.len > 0: ", failed:" & failed else: ""),
       reasons

proc vectors =
  echo "-- signature generation vectors"
  vectorFile("Wycheproof rsa_pkcs1_*_sig_gen", WycheproofTxt, parseRsaPrivateKeyDer)
  vectorFile("NIST CAVP SigGen15_186-3", NistTxt, parseRsaPrivateKeyDer)

proc ownSignatures =
  echo "-- Wycheproof messages, signed here, verified by std/crypto/rsa"
  for (bits, name) in [("2048", "test2048"), ("3072", "test3072"), ("4096", "test4096")]:
    var key = default(RsaPrivateKey)
    for (n, pem8, pem1) in Keys:
      if n == name: discard parseRsaPrivateKeyPem(pem8, key)
    var good = 0
    var total = 0
    var forged = 0
    for line in MessagesTxt.splitLines:
      let f = line.split(' ')
      if f.len == 3 and f[0] == "m" and f[1] == bits:
        inc total
        let msg = unhex(f[2])
        var sig: seq[byte] = @[]
        if rsaSignPkcs1v15(key, rhSha256, msg, sig) == rseNone and
           sig.len == key.modulusBits div 8 and
           rsaVerifyPkcs1v15(publicKey(key), rhSha256, msg, sig):
          inc good
        # the same signature with its last bit flipped, or over another message
        if sig.len > 0:
          var bad = sig
          bad[bad.len - 1] = bad[bad.len - 1] xor 1'u8
          if rsaVerifyPkcs1v15(publicKey(key), rhSha256, msg, bad): inc forged
          var other = msg
          other.add 0'u8
          if rsaVerifyPkcs1v15(publicKey(key), rhSha256, other, sig): inc forged
    echo bits, " bits: ", good, " of ", total, " verify, ", forged, " altered ones verify"

proc faults =
  echo "-- the fault check"
  var key = default(RsaPrivateKey)
  echo "dp-corrupt.der parses: ", parseRsaPrivateKeyDer(bytesOf(DpCorrupt), key)
  var sig = @[1'u8, 2, 3]
  let r = rsaSignPkcs1v15(key, rhSha256, bytesOf("hello nimony"), sig)
  echo "and signs: ", r, ", signature bytes: ", sig.len
  # flip one bit in each of a spread of bytes of dP, dQ and qInv of a good
  # key (the last 3 * 133 bytes of its DER); every flip that still parses
  # must be refused at signing time
  let der = pemBody(Keys[0][2])
  var parsed = 0
  var refused = 0
  var i = der.len - 3 * 133
  while i < der.len:
    var m = der
    m[i] = m[i] xor 0x10'u8
    var k = default(RsaPrivateKey)
    if parseRsaPrivateKeyDer(m, k) == rkeNone:
      inc parsed
      var s: seq[byte] = @[]
      if rsaSignPkcs1v15(k, rhSha256, bytesOf("hello nimony"), s) == rseFault and
         s.len == 0: inc refused
    i += 13
  echo "CRT bit flips that parse: ", parsed, ", refused to sign: ", refused
  var empty = default(RsaPrivateKey)
  sig = @[1'u8]
  echo "never-parsed key: ", rsaSignPkcs1v15(empty, rhSha256, @[], sig), ", ",
       sig.len, " bytes"
  sig = @[1'u8]
  discard parseRsaPrivateKeyPem("junk", key)
  echo "key whose parse failed: ", rsaSignPkcs1v15(key, rhSha256, @[], sig), ", ",
       sig.len, " bytes"

opensslGoldens()
jwtExample()
vectors()
ownSignatures()
faults()
